   ratified vault. ***
   anchor      : HUB_PARTY   (kind: hub, origin: data_7.js.parent)
   track       : unratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PARTY_HK
   hashdiff    : SAT_PARTY_CLAIM_HISTORY_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_NO_OF_CLAIMS_ON_PREV_POLICY as PREVIOUS_POLICY_CLAIM_COUNT
        , cast(null as varchar) as PRIOR_CLAIM_NARRATIVE
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PART_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as PREVIOUS_POLICY_CLAIM_COUNT
        , CLAIM_HISTORY as PRIOR_CLAIM_NARRATIVE
        , 'BJAZ_HC_PART_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hc_part_extn') }}
    where (nullif(trim(PART_ID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREVIOUS_POLICY_CLAIM_COUNT end) as PREVIOUS_POLICY_CLAIM_COUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRIOR_CLAIM_NARRATIVE end) as PRIOR_CLAIM_NARRATIVE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when PREVIOUS_POLICY_CLAIM_COUNT is not null or PRIOR_CLAIM_NARRATIVE is not null
                     then md5(upper(coalesce(cast(PREVIOUS_POLICY_CLAIM_COUNT as varchar), '') || '|' || coalesce(cast(PRIOR_CLAIM_NARRATIVE as varchar), '')))
                end as SAT_PARTY_CLAIM_HISTORY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_CLAIM_HISTORY_HASHDIFF is not null
